    sta prot_status_save                                              ; 8540: 8d 69 0d    .i.      ; Save old mask in prot_status_save for restore
    ora #&1c                                                          ; 8543: 09 1c       ..       ; Set bits 2-4: disable JSR/UserProc/OSProc
    sta prot_status                                                   ; 8545: 8d 68 0d    .h.      ; Write raised protection mask back
