; ***************************************************************************************
; Service call dispatch
;
; Handles service calls 1, 4, 8, 9, 13, 14, and 15.
;
; | Call | Meaning                     |
; |------|-----------------------------|
; | 1    | Absolute workspace claim    |
; | 4    | Unrecognised * command      |
; | 8    | Unrecognised OSWORD         |
; | 9    | *HELP                       |
; | 13   | ROM initialisation          |
; | 14   | ROM initialisation complete |
; | 15   | Vectors claimed             |
;
; On service 15 the ROM verifies the host OS via OSBYTE 0 with the input X=1, which
; returns the OS version code:
;
; | OSBYTE 1 value | Host                              |
; |----------------|-----------------------------------|
; | 0              | OS 1.00 (early BBC B or Electron) |
; | 1              | OS 1.20 or American OS            |
; | 2              | OS 2.00 (BBC B+)                  |
; | 3              | OS 3.2 / 3.5 (Master 128)         |
; | 4              | OS 4.0 (Master Econet Terminal)   |
; | 5              | OS 5.0 (Master Compact)           |
;
; Only Master 128 and Master Econet Terminal are supported. Any other version gets a Bad
; ROM <slot> message printed and its workspace byte cleared at &02A0 + adjusted-slot,
; effectively rejecting the ROM.
;
; On Entry:
;     A: service call number
;     X: ROM slot
;     Y: parameter
; &8a8c referenced 1 time by &8003
.service_handler
    pha                                                               ; 8a8c: 48          H        ; Save service call number
    cmp #&0f                                                          ; 8a8d: c9 0f       ..       ; Service call &0F (vectors claimed)?
    bne restore_rom_slot_entry                                        ; 8a8f: d0 36       .6       ; No: skip vectors-claimed handling
    phy                                                               ; 8a91: 5a          Z        ; Save Y on stack across the version-check
    lda #osbyte_read_os_version                                       ; 8a92: a9 00       ..       ; OSBYTE 0: read OS version
    ldx #1                                                            ; 8a94: a2 01       ..       ; X=1 to request version number
; On return, X is the OS version number:
;
; | X | Meaning                                   |
; |---|-------------------------------------------|
; | 0 | OS 1.00 (Early BBC B or Electron OS 1.00) |
; | 1 | OS 1.20 or American OS                    |
; | 2 | OS 2.00 (BBC B+)                          |
; | 3 | OS 3.2/3.5 (Master 128)                   |
; | 4 | OS 4.0 (Master Econet Terminal)           |
; | 5 | OS 5.0 (Master Compact)                   |
    jsr osbyte                                                        ; 8a96: 20 f4 ff     ..      ; X=1, OS 1.20 or American OS
    lda os_spool_flag_table,x                                         ; 8a99: bd 20 8a    . .      ; X is the host OS version (0=1.00, 1=1.20, 3=Master, 4=Master Terminal, 5=Master Compact)
    sta spool_control_flag                                            ; 8a9c: 8d 71 0d    .q.      ; Store the spool-control flag
    cpx #3                                                            ; 8a9f: e0 03       ..       ; OS 3.2/3.5 (Master 128)?
    bcs restore_rom_slot                                              ; 8aa1: b0 21       .!       ; C set: not ours, restore ROM slot and return
    txa                                                               ; 8aa3: 8a          .        ; Transfer OS version to A
    php                                                               ; 8aa4: 08          .        ; Save flags (Z set if OS 1.00) across print
    jsr print_inline                                                  ; 8aa5: 20 6c 92     l.      ; Print '<CR>Bad ROM ' to mark non-Master OS
    equb &0d, "Bad ROM "                                              ; 8aa8: 0d 42 61... .Ba...   ; svc 13 fail path
    lda romsel_copy                                                   ; 8ab1: a5 f4       ..       ; Load this ROM's slot number
    jsr print_num_no_leading                                          ; 8ab3: 20 5c b3     \.      ; Print slot number as decimal
    jsr print_newline_no_spool                                        ; 8ab6: 20 04 92     ..      ; Print trailing newline, bypassing *SPOOL
    ldx romsel_copy                                                   ; 8ab9: a6 f4       ..       ; Reload ROM slot for workspace clearing
    plp                                                               ; 8abb: 28          (        ; Restore flags
    beq clear_workspace_byte                                          ; 8abc: f0 01       ..       ; OS 1.00: skip INX (table starts at slot 0)
    inx                                                               ; 8abe: e8          .        ; Adjust index for OS 1.20/2.00/5.00 layout
; &8abf referenced 1 time by &8abc
.clear_workspace_byte
    lda #0                                                            ; 8abf: a9 00       ..       ; A=0
    sta rom_type_table,x                                              ; 8ac1: 9d a0 02    ...      ; Clear workspace byte for this ROM
; &8ac4 referenced 1 time by &8aa1
.restore_rom_slot
    ldx romsel_copy                                                   ; 8ac4: a6 f4       ..       ; Restore ROM slot to X
    ply                                                               ; 8ac6: 7a          z        ; Restore Y from stack
; &8ac7 referenced 1 time by &8a8f
.restore_rom_slot_entry
    pla                                                               ; 8ac7: 68          h        ; Pop service call number into A
    pha                                                               ; 8ac8: 48          H        ; Re-save service call number
.check_adlc_flag
    lda rom_ws_pages,x                                                ; 8ac9: bd f0 0d    ...      ; Load ROM slot flag byte
    asl a                                                             ; 8acc: 0a          .        ; Shift bit 7 (ADLC absent) into carry
    pla                                                               ; 8acd: 68          h        ; Restore service call number
    bcc dispatch_svc_with_state                                       ; 8ace: 90 01       ..       ; ADLC present: continue dispatch
    rts                                                               ; 8ad0: 60          `        ; ADLC absent: decline service, return
; &8ad1 referenced 1 time by &8ace
.dispatch_svc_with_state
    tax                                                               ; 8ad1: aa          .        ; Transfer service number to X
    lda svc_state                                                     ; 8ad2: a5 a9       ..       ; Save current service state
    pha                                                               ; 8ad4: 48          H        ; Push old state
    txa                                                               ; 8ad5: 8a          .        ; Restore service number to A
    sta svc_state                                                     ; 8ad6: 85 a9       ..       ; Store as current service state
    cmp #&0d                                                          ; 8ad8: c9 0d       ..       ; Service < 13?
    bcc dispatch_svc_index                                            ; 8ada: 90 1c       ..       ; Yes: use as dispatch index directly
    sbc #5                                                            ; 8adc: e9 05       ..       ; Subtract 5 (map 13-17 to 8-12)
    cmp #&0d                                                          ; 8ade: c9 0d       ..       ; Mapped value = 13? (original was 18)
    beq dispatch_svc_index                                            ; 8ae0: f0 16       ..       ; Yes: valid service 18 (FS select)
    bcc dispatch_svc_state_check                                      ; 8ae2: 90 12       ..       ; C clear: service number was below the prior CMP threshold, take dispatch fall-through
    sbc #5                                                            ; 8ae4: e9 05       ..       ; Subtract 5 to remap service range
    cmp #&0e                                                          ; 8ae6: c9 0e       ..       ; Compare with &0E
    beq dispatch_svc_index                                            ; 8ae8: f0 0e       ..       ; Equal: dispatch directly
    bcc dispatch_svc_state_check                                      ; 8aea: 90 0a       ..       ; Below: take dispatch fall-through
    sbc #8                                                            ; 8aec: e9 08       ..       ; Subtract 8 to remap further
    cmp #&0f                                                          ; 8aee: c9 0f       ..       ; Compare with &0F
    bcc dispatch_svc_state_check                                      ; 8af0: 90 04       ..       ; Below: dispatch fall-through
    cmp #&18                                                          ; 8af2: c9 18       ..       ; Compare with &18
    bcc dispatch_svc_index                                            ; 8af4: 90 02       ..       ; Below: dispatch index now in A
; &8af6 referenced 3 times by &8ae2, &8aea, &8af0
.dispatch_svc_state_check
    lda #0                                                            ; 8af6: a9 00       ..       ; Unknown service: set index to 0
; &8af8 referenced 4 times by &8ada, &8ae0, &8ae8, &8af4
.dispatch_svc_index
    tax                                                               ; 8af8: aa          .        ; Transfer dispatch index to X
    beq restore_svc_state                                             ; 8af9: f0 0e       ..       ; Index 0: unhandled service, skip
    lda ws_page                                                       ; 8afb: a5 a8       ..       ; Save current workspace page
    pha                                                               ; 8afd: 48          H        ; Push old page
    sty ws_page                                                       ; 8afe: 84 a8       ..       ; Set workspace page from Y parameter
    tya                                                               ; 8b00: 98          .        ; Transfer Y to A
    ldy #0                                                            ; 8b01: a0 00       ..       ; Y=0 for dispatch offset
    jsr svc_dispatch                                                  ; 8b03: 20 7b 8e     {.      ; Dispatch to service handler via table
    pla                                                               ; 8b06: 68          h        ; Restore old workspace page
    sta ws_page                                                       ; 8b07: 85 a8       ..       ; Store it back
; &8b09 referenced 1 time by &8af9
.restore_svc_state
    ldx svc_state                                                     ; 8b09: a6 a9       ..       ; Get service state (return code)
    pla                                                               ; 8b0b: 68          h        ; Restore old service state
    sta svc_state                                                     ; 8b0c: 85 a9       ..       ; Store it back
    txa                                                               ; 8b0e: 8a          .        ; Transfer return code to A
.restore_romsel_rts
    ldx romsel_copy                                                   ; 8b0f: a6 f4       ..       ; Restore ROM slot to X
    rts                                                               ; 8b11: 60          `        ; Return to MOS
; ***************************************************************************************
; *ROFF command handler
;
; Disables remote operation by clearing the flag at offset 0 in the receive block. If
; remote operation was active, re-enables the keyboard via OSBYTE &C9 (with X=0, Y=0) and
; calls tx_econet_abort with A=&0A to reinitialise the workspace area. Falls through to
; scan_remote_keys which clears svc_state and nfs_workspace.
;
; On Entry:
;     Y: command line offset (unused -- *ROFF takes no args)
;
; On Exit:
;     A, X, Y: clobbered
.cmd_roff
    ldy #0                                                            ; 8b12: a0 00       ..       ; Offset 0 in receive block
    lda (net_rx_ptr),y                                                ; 8b14: b1 9c       ..       ; Load remote operation flag
    beq clear_svc_and_ws                                              ; 8b16: f0 21       .!       ; Zero: already off, skip to cleanup
    lda #0                                                            ; 8b18: a9 00       ..       ; A=0
    tax                                                               ; 8b1a: aa          .        ; Copy A to X
    sta (net_rx_ptr),y                                                ; 8b1b: 91 9c       ..       ; Clear remote operation flag
    tay                                                               ; 8b1d: a8          .        ; Copy A to Y
    lda #osbyte_econet_kbd_disable                                    ; 8b1e: a9 c9       ..       ; OSBYTE &C9: keyboard disable
    jsr osbyte                                                        ; 8b20: 20 f4 ff     ..      ; osbyte: econet kbd disable
    lda #&0a                                                          ; 8b23: a9 0a       ..       ; A=&0A: workspace init parameter
    jsr tx_econet_abort                                               ; 8b25: 20 62 ad     b.      ; Initialise workspace area
; ***************************************************************************************
; Scan keyboard for remote-operation keys
;
; Uses OSBYTE &7A with Y=&7F to check whether remote-operation keys (&CE..&CF) are
; currently pressed. If neither key is detected, clears svc_state and nfs_workspace to
; zero via the clear_svc_and_ws entry point (also used directly by cmd_roff). Called by
; check_escape.
;
; X is saved into nfs_workspace across the OSBYTE call and restored each iteration – the
; loop reuses A as the key-code counter without needing X. clear_svc_and_ws is also
; entered directly (label) by cmd_roff with no register pre-conditions.
