    lda tx_imm_idx_base,y                                             ; a869: b9 ed 00    ...      ; Load OSWORD parameter byte
    sta svc_state,y                                                   ; a86c: 99 a9 00    ...      ; Copy parameter to workspace
    dey                                                               ; a86f: 88          .        ; Next slot
; &a870 referenced 1 time by &a856
