    lsr a                                                             ; a8d5: 4a          J        ; Shift high nibble down (2 of 4)
    lsr a                                                             ; a8d6: 4a          J        ; Shift high nibble down (3 of 4)
    lsr a                                                             ; a8d7: 4a          J        ; Shift high nibble down (4 of 4)
