    sta (nfs_workspace),y                                             ; ad64: 91 9e       ..       ; Store the abort code (passed in A) at workspace[&D9]
    lda #&80                                                          ; ad66: a9 80       ..       ; A=&80: control = immediate-operation flag
    ldy #&0c                                                          ; ad68: a0 0c       ..       ; Y=&0C: TXCB control-byte offset
    sta (nfs_workspace),y                                             ; ad6a: 91 9e       ..       ; Set TXCB[&0C] = &80 (immediate / abort)
    lda net_tx_ptr                                                    ; ad6c: a5 9a       ..       ; Save current net_tx_ptr low (we'll repoint TX at the abort packet)
    pha                                                               ; ad6e: 48          H        ; Push it for restore on exit
    lda net_tx_ptr_hi                                                 ; ad6f: a5 9b       ..       ; Save net_tx_ptr high too
    pha                                                               ; ad71: 48          H        ; Push it
    sty net_tx_ptr                                                    ; ad72: 84 9a       ..       ; TX low = &0C (abort packet starts at workspace[&0C])
    ldx nfs_workspace_hi                                              ; ad74: a6 9f       ..       ; Get nfs_workspace high byte
    stx net_tx_ptr_hi                                                 ; ad76: 86 9b       ..       ; TX high = workspace page (so net_tx_ptr now points at the abort packet in workspace)
    jsr send_net_packet                                               ; ad78: 20 2c 9b     ,.      ; Send the abort packet via the standard TX path
    lda #&3f                                                          ; ad7b: a9 3f       .?       ; A=&3F: TXCB status = abort-complete sentinel
    sta (net_tx_ptr,x)                                                ; ad7d: 81 9a       ..       ; Write status via (net_tx_ptr,X) -- mark TX done
    pla                                                               ; ad7f: 68          h        ; Pull saved net_tx_ptr high
    sta net_tx_ptr_hi                                                 ; ad80: 85 9b       ..       ; Restore
    pla                                                               ; ad82: 68          h        ; Pull saved net_tx_ptr low
    sta net_tx_ptr                                                    ; ad83: 85 9a       ..       ; Restore -- caller's TX state intact
    rts                                                               ; ad85: 60          `        ; Return
; ***************************************************************************************
; OSWORD 7 handler: claim/release network resources
