    ldx #&0a                                                          ; ad8e: a2 0a       ..       ; X=&0A: scan first 11 entries (table indices 0..&0A)
    jsr match_rx_code                                                 ; ad90: 20 da ad     ..      ; Look up A in the claim code table
    beq process_match_result                                          ; ad93: f0 0a       ..       ; Match: handle as state 2
    dey                                                               ; ad95: 88          .        ; DEY: Y=0 (state 3 marker, two DEYs from 1)
    dey                                                               ; ad96: 88          .        ; Y=-1: flag second range
    ldx #&11                                                          ; ad97: a2 11       ..       ; X=&11: scan all 18 entries (state 3 also accepts the extended range)
    jsr match_rx_code                                                 ; ad99: 20 da ad     ..      ; Look up A again with extended range
    beq process_match_result                                          ; ad9c: f0 01       ..       ; Match: handle as state 3
