; &adaa referenced 1 time by &adb2
.loop_save_tube_bytes
    lda tube_claimed_id,y                                             ; adaa: b9 15 00    ...      ; Read tube_claimed_id,Y
    sta (nfs_workspace),y                                             ; adad: 91 9e       ..       ; Save in workspace[&DC..]
    dey                                                               ; adaf: 88          .        ; Step backwards
    cpy #&da                                                          ; adb0: c0 da       ..       ; Done at &DA?
    bpl loop_save_tube_bytes                                          ; adb2: 10 f6       ..       ; Loop while Y > &DA (saves &DA, &DB, &DC -- 3 bytes)
