    lda #&7f                                                          ; adbb: a9 7f       ..       ; A=&7F: 'pending response' control value
    ldy #&0c                                                          ; adbd: a0 0c       ..       ; Y=&0C: TXCB control offset
    sta (nfs_workspace),y                                             ; adbf: 91 9e       ..       ; Mark TXCB as pending
; &adc1 referenced 1 time by &adc3
.loop_poll_ws_status
