    bpl loop_poll_ws_status                                           ; adc3: 10 fc       ..       ; Bit 7 still clear: keep polling for response
    tsx                                                               ; adc5: ba          .        ; Capture S so we can patch the caller's stack frame
    ldy #&dd                                                          ; adc6: a0 dd       ..       ; Y=&DD: highest workspace offset for the response copy
    lda (nfs_workspace),y                                             ; adc8: b1 9e       ..       ; Read first response byte (workspace[&DD])
