    beq rts_match_rx_code                                             ; addd: f0 03       ..       ; Match: return with Z set
    dex                                                               ; addf: ca          .        ; Step to next earlier table entry
    bpl match_rx_code                                                 ; ade0: 10 f8       ..       ; Loop while X >= 0 (table walked top-down)
; &ade2 referenced 2 times by &addd, &adfd
.rts_match_rx_code
    rts                                                               ; ade2: 60          `        ; Return; Z reflects last CMP
