    cmp #7                                                            ; adf7: c9 07       ..       ; Is the OSWORD number 7?
    beq copy_pb_to_ws                                                 ; adf9: f0 04       ..       ; Yes: handle as either 7 or 8 -- both copy PB to ws
    cmp #8                                                            ; adfb: c9 08       ..       ; Is the OSWORD number 8?
    bne rts_match_rx_code                                             ; adfd: d0 e3       ..       ; Neither 7 nor 8: return early (other OSWORDs handled elsewhere)
; &adff referenced 1 time by &adf9
.copy_pb_to_ws
    ldx #&db                                                          ; adff: a2 db       ..       ; X=&DB: workspace offset for the PB copy
    stx nfs_workspace                                                 ; ae01: 86 9e       ..       ; Temporarily reuse nfs_workspace as the destination low byte (high byte already points at the workspace page)
; &ae03 referenced 1 time by &ae08
.loop_copy_pb_to_ws
