    sta (nfs_workspace),y                                             ; ae05: 91 9e       ..       ; Write to (nfs_workspace),Y -- effectively writes to workspace[&DB+Y]
    dey                                                               ; ae07: 88          .        ; Step backwards through the 15 bytes
    bpl loop_copy_pb_to_ws                                            ; ae08: 10 f9       ..       ; Loop while Y >= 0
    iny                                                               ; ae0a: c8          .        ; Bring Y back to 0 for the next single-byte write
    dec nfs_workspace                                                 ; ae0b: c6 9e       ..       ; Decrement nfs_workspace low byte: now points at workspace[&DA] (one before the copied region)
    lda osbyte_a_copy                                                 ; ae0d: a5 ef       ..       ; Read original OSWORD number from osbyte_a_copy
    sta (nfs_workspace),y                                             ; ae0f: 91 9e       ..       ; Store at workspace[&DA] -- so the abort packet header carries the OSWORD number
    sty nfs_workspace                                                 ; ae11: 84 9e       ..       ; Restore nfs_workspace to its proper low byte (Y=0)
    ldy #&14                                                          ; ae13: a0 14       ..       ; Y=&14: TXCB control offset
