    equb &80                                                          ; b039: 80          .        ; ctrl=&80 (standard TX)
    equb &9f                                                          ; b03a: 9f          .        ; port=&9F
    equb &00                                                          ; b03b: 00          .        ; dest station=&00 (filled later)
    equb &00                                                          ; b03c: 00          .        ; dest network=&00 (filled later)
    equb &b9                                                          ; b03d: b9          .     
    equb &8e                                                          ; b03e: 8e          .        ; buf start hi (&8E); start = &8EB9
    equb &ff                                                          ; b03f: ff          .        ; buf start ext lo=&FF
    equb &ff                                                          ; b040: ff          .        ; buf start ext hi=&FF
    equb &c1                                                          ; b041: c1          .     
    equb &8e                                                          ; b042: 8e          .        ; buf end hi (&8E); end = &8EA7
    equb &ff                                                          ; b043: ff          .        ; buf end ext lo=&FF
    equb &ff                                                          ; b044: ff          .        ; buf end ext hi=&FF
; ***************************************************************************************
; Palette-RX control-block template (12 bytes)
;
; 12-byte template used by the *PS / palette-RX paths. Copied with marker processing: &FD
; skips the destination byte (preserving the existing field), &FC substitutes
; net_rx_ptr_hi (the caller's RX-buffer page). Filled in over the workspace TXCB by the
; broadcast-RX setup before the request is dispatched.
; &b045 used as index base 1 time by &af4c
.rx_palette_txcb_template
    equb &7f                                                          ; b045: 7f          .        ; ctrl=&7F (RX listen)
    equb &9e                                                          ; b046: 9e          .        ; port=&9E
    equb &fd                                                          ; b047: fd          .     
    equb &fd                                                          ; b048: fd          .     
    equb &2e                                                          ; b049: 2e          .     
    equb &fc                                                          ; b04a: fc          .        ; buf start hi=page ptr (&FC)
    equb &ff                                                          ; b04b: ff          .        ; buf start ext lo=&FF
    equb &ff                                                          ; b04c: ff          .        ; buf start ext hi=&FF
    equb &31                                                          ; b04d: 31          1     
    equb &fc                                                          ; b04e: fc          .     
    equb &ff                                                          ; b04f: ff          .        ; buf end ext lo=&FF
    equb &ff                                                          ; b050: ff          .        ; buf end ext hi=&FF
; ***************************************************************************************
; Language reply 2: save palette / VDU state
;
; Reached via the language-reply dispatch table when a remote sends reply code 2 ('save
; palette and VDU state'). Saves the current template byte from osword_flag on the stack,
; sets up the workspace pointer (nfs_workspace) to the appropriate offset, and copies the
; palette / VDU state from MOS workspace at &0350 into the workspace transmit buffer for
; forwarding back to the station.
.lang_2_save_palette_vdu
    lda osword_flag                                                   ; b051: a5 aa       ..       ; Read osword_flag (preserved across the dispatch)
    pha                                                               ; b053: 48          H        ; Save state byte
    lda #&e9                                                          ; b054: a9 e9       ..       ; A=&E9: workspace start lo for palette save
    sta nfs_workspace                                                 ; b056: 85 9e       ..       ; Store as nfs_workspace lo
    ldy #0                                                            ; b058: a0 00       ..       ; Y=0
    sty osword_flag                                                   ; b05a: 84 aa       ..       ; Reset osword_flag = 0
    lda vdu_screen_mode                                               ; b05c: ad 50 03    .P.      ; Read vdu_screen_mode (MOS state byte)
    sta (nfs_workspace),y                                             ; b05f: 91 9e       ..       ; Store at (nfs_workspace)+0
    inc nfs_workspace                                                 ; b061: e6 9e       ..       ; Advance nfs_workspace lo
    lda vdu_display_start_hi                                          ; b063: ad 51 03    .Q.      ; Read vdu_display_start_hi (next MOS byte)
    pha                                                               ; b066: 48          H        ; Save another byte
    tya                                                               ; b067: 98          .        ; A=0 for first palette entry
; &b068 referenced 1 time by &b087
.loop_read_palette
    sta (nfs_workspace),y                                             ; b068: 91 9e       ..       ; Store at (nfs_workspace)
    ldx nfs_workspace                                                 ; b06a: a6 9e       ..       ; Read updated nfs_workspace lo
    ldy nfs_workspace_hi                                              ; b06c: a4 9f       ..       ; Read nfs_workspace hi
    lda #osword_read_palette                                          ; b06e: a9 0b       ..       ; A=&0B: OSWORD &0B = read palette entry
    jsr osword                                                        ; b070: 20 f1 ff     ..      ; Read palette entry  Read palette
    pla                                                               ; b073: 68          h        ; Restore inner saved
    ldy #0                                                            ; b074: a0 00       ..       ; Y=0
    sta (nfs_workspace),y                                             ; b076: 91 9e       ..       ; Store palette result at workspace
    iny                                                               ; b078: c8          .        ; Y=1: physical colour offset
    lda (nfs_workspace),y                                             ; b079: b1 9e       ..       ; Re-read palette result
    pha                                                               ; b07b: 48          H        ; Save for next iteration
    ldx nfs_workspace                                                 ; b07c: a6 9e       ..       ; Read updated workspace lo
    inc nfs_workspace                                                 ; b07e: e6 9e       ..       ; Advance workspace
    inc osword_flag                                                   ; b080: e6 aa       ..       ; Increment osword_flag (palette index)
    dey                                                               ; b082: 88          .        ; Y=0
    lda osword_flag                                                   ; b083: a5 aa       ..       ; Read updated osword_flag
    cpx #&f9                                                          ; b085: e0 f9       ..       ; Compare with &F9 (last palette entry)
    bne loop_read_palette                                             ; b087: d0 df       ..       ; Not done: loop
    pla                                                               ; b089: 68          h        ; Restore outer saved
    sty osword_flag                                                   ; b08a: 84 aa       ..       ; Reset osword_flag = 0 after palette loop
    inc nfs_workspace                                                 ; b08c: e6 9e       ..       ; Advance workspace
    jsr serialise_palette_entry                                       ; b08e: 20 9d b0     ..      ; Serialise the next palette entry
    inc nfs_workspace                                                 ; b091: e6 9e       ..       ; Advance workspace
    pla                                                               ; b093: 68          h        ; Restore final saved
    sta osword_flag                                                   ; b094: 85 aa       ..       ; Save osword_flag
; ***************************************************************************************
; Copy current state byte to committed state
;
; Reads the working state byte from workspace and stores it to the committed state
; location. Used to finalise a state transition after all related workspace fields have
; been updated.
;
; On Exit:
;     A: = the committed value
; &b096 referenced 4 times by &9856, &987e, &98b6, &a9b9
.commit_state_byte
    lda prot_status_save                                              ; b096: ad 69 0d    .i.      ; Read saved copy of prot_status from prot_status_save
    sta prot_status                                                   ; b099: 8d 68 0d    .h.      ; Store back to prot_status
    rts                                                               ; b09c: 60          `        ; Return
; ***************************************************************************************
; Serialise palette register to workspace
;
; Reads the current logical colour for a palette register via OSBYTE &0B and stores both
; the palette value and the display mode information in the workspace block. Used during
; remote screen state capture.
;
; On Entry:
;     X: palette register index (0-15)
;     Y: destination workspace offset (palette + mode pair)
;
; On Exit:
;     Y: advanced past the 2-byte pair
;     A, X: clobbered (OSBYTE)
; &b09d referenced 1 time by &b08e
.serialise_palette_entry
    lda vdu_mode                                                      ; b09d: ad 55 03    .U.      ; Read vdu_mode (current palette index)
    tax                                                               ; b0a0: aa          .        ; Copy A to X
    ora #&40                                                          ; b0a1: 09 40       .@       ; Mark as palette entry
    sta (nfs_workspace),y                                             ; b0a3: 91 9e       ..       ; Store at (nfs_workspace)+Y
    inc nfs_workspace                                                 ; b0a5: e6 9e       ..       ; Advance workspace
    tya                                                               ; b0a7: 98          .        ; A = current Y (= 0)
    sta (nfs_workspace),y                                             ; b0a8: 91 9e       ..       ; Store 0 at (nfs_workspace)+Y
    lda read_osbyte_table,x                                           ; b0aa: bd ce b0    ...      ; Read lookup byte from read_osbyte_table+X
    ldx #0                                                            ; b0ad: a2 00       ..       ; X=0: indexed-indirect mode
    inc nfs_workspace                                                 ; b0af: e6 9e       ..       ; Advance workspace
    sta (nfs_workspace,x)                                             ; b0b1: 81 9e       ..       ; Store at (nfs_workspace,X)
    jsr read_osbyte_to_ws_x0                                          ; b0b3: 20 b6 b0     ..      ; Read OSBYTE result via x=0 helper
; ***************************************************************************************
; Read OSBYTE with X=0 and store to workspace
;
; Sets X=0 then falls through to read_osbyte_to_ws to issue the OSBYTE call and store the
; result. Used when the OSBYTE parameter X must be zero.
;
; On Entry:
;     Y: destination workspace offset
;
; On Exit:
;     Y: incremented past the stored byte
;     A, X: clobbered (OSBYTE)
; &b0b6 referenced 1 time by &b0b3
.read_osbyte_to_ws_x0
    ldx #0                                                            ; b0b6: a2 00       ..       ; X=0: zero-arg helper entry
; ***************************************************************************************
; Issue OSBYTE from table and store result
;
; Loads the OSBYTE function code from the next entry in the OSBYTE table, issues the
; call, and stores the Y result in workspace at the current offset. Advances the table
; pointer for the next call.
;
; On Entry:
;     X: OSBYTE X parameter
;     Y: destination workspace offset
;
; On Exit:
;     Y: incremented past the stored byte
;     A, X: clobbered
.read_osbyte_to_ws
    ldy osword_flag                                                   ; b0b8: a4 aa       ..       ; Y = osword_flag (OSBYTE-table index)
    inc osword_flag                                                   ; b0ba: e6 aa       ..       ; Increment osword_flag for next call
    inc nfs_workspace                                                 ; b0bc: e6 9e       ..       ; Advance nfs_workspace
    lda read_osbyte_return,y                                          ; b0be: b9 cc b0    ...      ; Load OSBYTE number from read_osbyte_return+Y
    ldy #&ff                                                          ; b0c1: a0 ff       ..       ; Y=&FF -- OSBYTE arg (read mode)
    jsr osbyte                                                        ; b0c3: 20 f4 ff     ..      ; Issue OSBYTE
    txa                                                               ; b0c6: 8a          .        ; Result to A
    ldx #0                                                            ; b0c7: a2 00       ..       ; X=0: indexed-indirect mode
    sta (nfs_workspace,x)                                             ; b0c9: 81 9e       ..       ; Store at (nfs_workspace,X)
    rts                                                               ; b0cb: 60          `        ; Return
; &b0cc used as index base 1 time by &b0be
.read_osbyte_return
    equb &c2, &c3                                                     ; b0cc: c2 c3       ..    
; &b0ce used as index base 1 time by &b0aa
.read_osbyte_table
    equs "000@XX`"                                                    ; b0ce: 30 30 30... 000...
.cmd_cdir_indirect_dispatch
; ***************************************************************************************
; *CDir command handler
;
; Parses an optional allocation size argument: if absent, defaults to index 2 (standard
; 19-entry directory, &200 bytes); if present, parses the decimal value and searches a
; 26-entry threshold table to find the matching allocation size index. Parses the
; directory name via parse_filename_arg, copies it to the TX buffer, and sends FS command
; code &1B to create the directory.
;
; Reached via PHA/PHA/RTS dispatch from cmd_table_fs entry *Cdir; the byte at the entry-1
; address &B0D5 happens to decode as JMP (cdir_unused_dispatch_table,X) but is never
; executed.
;
; On Entry:
;     Y: command line offset in text pointer
cmd_cdir = cmd_cdir_indirect_dispatch+1
    jmp (cdir_unused_dispatch_table,x)                                ; b0d5: 7c 98 48    |.H      ; JMP (cdir_unused_dispatch_table,X) -- never executed; see cmd_cdir  Save command line offset  Push onto stack
    jsr mask_owner_access                                             ; b0d8: 20 04 b3     ..      ; Set owner-only access mask
    jsr skip_to_next_arg                                              ; b0db: 20 b4 b3     ..      ; Skip to optional size argument
    cmp #&0d                                                          ; b0de: c9 0d       ..       ; End of line?
    bne parse_cdir_size                                               ; b0e0: d0 04       ..       ; No: parse size argument
    ldx #2                                                            ; b0e2: a2 02       ..       ; Default allocation size index = 2
    bne done_cdir_size                                                ; b0e4: d0 0f       ..       ; Branch when the *CDIR size is complete
; &b0e6 referenced 1 time by &b0e0
.parse_cdir_size
    lda #&ff                                                          ; b0e6: a9 ff       ..       ; A=&FF: mark as decimal parse
    sta fs_work_4                                                     ; b0e8: 85 b4       ..       ; Store decimal parse flag
    jsr parse_addr_arg                                                ; b0ea: 20 bd 92     ..      ; Parse numeric size argument
    ldx #&1b                                                          ; b0ed: a2 1b       ..       ; X=&1B: top of 26-entry size table
; &b0ef referenced 1 time by &b0f3
.loop_find_alloc_size
    dex                                                               ; b0ef: ca          .        ; Try next lower index
    cmp cdir_size_thresholds,x                                        ; b0f0: dd 09 b1    ...      ; Compare size with threshold
    bcc loop_find_alloc_size                                          ; b0f3: 90 fa       ..       ; A < threshold: keep searching
; &b0f5 referenced 1 time by &b0e4
.done_cdir_size
    stx hazel_txcb_data                                               ; b0f5: 8e 05 c1    ...      ; Store allocation size index
    pla                                                               ; b0f8: 68          h        ; Restore command line offset
    tay                                                               ; b0f9: a8          .        ; Transfer to Y
    jsr save_ptr_to_os_text                                           ; b0fa: 20 a8 b3     ..      ; Save text pointer for filename parse
    jsr parse_filename_arg                                            ; b0fd: 20 61 b2     a.      ; Parse directory name argument
    ldx #1                                                            ; b100: a2 01       ..       ; X=1: one argument to copy
    jsr copy_arg_to_buf                                               ; b102: 20 d6 b2     ..      ; Copy directory name to TX buffer
    ldy #&1b                                                          ; b105: a0 1b       ..       ; Y=&1B: *CDir FS command code
.cdir_dispatch_col
; &b109 used as index base 1 time by &b0f0
cdir_size_thresholds = cdir_dispatch_col+2
    jmp save_net_tx_cb                                                ; b107: 4c 8a 97    L..      ; Send command to file server
; ***************************************************************************************
; *CDir allocation size threshold table (26 entries)
;
; 26 thresholds dividing 0-255 into size classes for the *CDir directory-size argument.
; Table base is at cdir_dispatch_col+2 (overlapping the JMP operand high byte just before
; the table); the search loop (LDX #&1B / DEX / CMP table,X / BCC) scans indices 26 down
; to 0. Index 0 reads &94 from the JMP and is unreachable because index 1 (threshold &00)
; always matches first. The resulting X (1-26) is the allocation size class sent to the
; file server. Default when no size argument is given: index 2.
.cdir_alloc_size_table
    equb &00                                                          ; b10a: 00          .        ; Index 1: threshold 0 (catch-all)
    equb &0a                                                          ; b10b: 0a          .        ; Index 2: threshold 10 (default)
    equb &14                                                          ; b10c: 14          .        ; Index 3: threshold 20
    equb &1d                                                          ; b10d: 1d          .        ; Index 4: threshold 29
    equb &27                                                          ; b10e: 27          '        ; Index 5: threshold 39
    equb &31                                                          ; b10f: 31          1        ; Index 6: threshold 49
    equb &3b                                                          ; b110: 3b          ;        ; Index 7: threshold 59
    equb &45                                                          ; b111: 45          E        ; Index 8: threshold 69
    equb &4f                                                          ; b112: 4f          O        ; Index 9: threshold 79
    equb &58                                                          ; b113: 58          X        ; Index 10: threshold 88
    equb &62                                                          ; b114: 62          b        ; Index 11: threshold 98
    equb &6c                                                          ; b115: 6c          l        ; Index 12: threshold 108
    equb &76                                                          ; b116: 76          v        ; Index 13: threshold 118
    equb &80                                                          ; b117: 80          .        ; Index 14: threshold 128
    equb &8a                                                          ; b118: 8a          .        ; Index 15: threshold 138
    equb &94                                                          ; b119: 94          .        ; Index 16: threshold 148
    equb &9d                                                          ; b11a: 9d          .        ; Index 17: threshold 157
    equb &a7                                                          ; b11b: a7          .        ; Index 18: threshold 167
    equb &b1                                                          ; b11c: b1          .        ; Index 19: threshold 177
    equb &bb                                                          ; b11d: bb          .        ; Index 20: threshold 187
    equb &c5                                                          ; b11e: c5          .        ; Index 21: threshold 197
    equb &cf                                                          ; b11f: cf          .        ; Index 22: threshold 207
    equb &d8                                                          ; b120: d8          .        ; Index 23: threshold 216
    equb &e2                                                          ; b121: e2          .        ; Index 24: threshold 226
    equb &ec                                                          ; b122: ec          .        ; Index 25: threshold 236
; &b123 used as index base 1 time by &8fa2
.cdir_size_done
    equb &f6                                                          ; b123: f6          .        ; Index 26: threshold &F6 (246) -- last cdir-size threshold; doubles as cdir_size_done[0] (unread by init loop)
    equb &ff                                                          ; b124: ff          .        ; cdir_size_done[1] = &FF -> tx_retry_count (retry counter init)
    equb &28                                                          ; b125: 28          (        ; cdir_size_done[2] = &28 -> rx_wait_timeout (40 retries)
    equb &0a                                                          ; b126: 0a          .        ; cdir_size_done[3] = &0A -> peek_retry_count (10 retries)
; ***************************************************************************************
; *LCat command handler
;
; Rotates the caller's carry into bit 7 of hazel_fs_lib_flags (the dispatch path enters
; with C=1 so this sets the 'library' flag), then SEC / BCS unconditionally jumps to
; cat_set_lib_flag inside cmd_ex to catalogue the library directory with three entries
; per column.
;
; On Entry:
;     Y: command line offset in text pointer
;     C: 1 (set by the cmd_table_fs dispatch path)
.cmd_lcat
    ror hazel_fs_lib_flags                                            ; b127: 6e 71 c2    nq.      ; Rotate carry into lib flag bit 7
    sec                                                               ; b12a: 38          8        ; Set carry (= library directory)
    bcs cat_set_lib_flag                                              ; b12b: b0 29       .)       ; C set: set the library flag
; ***************************************************************************************
; *LEx command handler
;
; Rotates the caller's carry into bit 7 of hazel_fs_lib_flags (the dispatch path enters
; with C=1 so this sets the 'library' flag), then jumps to ex_set_lib_flag inside cmd_ex
; to examine the library directory with one entry per line.
;
; On Entry:
;     Y: command line offset in text pointer
;     C: 1 (set by the cmd_table_fs dispatch path)
.cmd_lex
    ror hazel_fs_lib_flags                                            ; b12d: 6e 71 c2    nq.      ; Rotate carry into lib flag bit 7
    sec                                                               ; b130: 38          8        ; Set carry (= library directory)
    bcs ex_set_lib_flag                                               ; b131: b0 09       ..       ; C set: set the library flag
.ps_scan_resume
    jsr set_text_and_xfer_ptr                                         ; b133: 20 da 93     ..      ; Set OS text pointer and FS-options transfer ptr
    ldy #0                                                            ; b136: a0 00       ..       ; Y=0: TX-buffer offset for the first byte
; ***************************************************************************************
; *Ex command handler
;
; Unified handler for *Ex, *LCat, and *LEx. Sets the library flag from carry (CLC for
; current, SEC for library). Configures column format: 1 entry per line for Ex (command
; 3), 3 per column for Cat (command &0B). Sends the examine request (code &12), then
; prints the directory header: title, cycle number, Owner/Public label, option name, Dir.
; and Lib. paths. Paginates through entries, printing each via ex_print_col_sep until the
; server returns zero entries.
;
; On Entry:
;     Y: command line offset in text pointer
.cmd_ex
    ror hazel_fs_lib_flags                                            ; b138: 6e 71 c2    nq.      ; Rotate carry into lib flag bit 7
    clc                                                               ; b13b: 18          .        ; Clear carry (= current directory)
; &b13c referenced 1 time by &b131
.ex_set_lib_flag
    rol hazel_fs_lib_flags                                            ; b13c: 2e 71 c2    .q.      ; Rotate carry back, clearing bit 7
    lda #&ff                                                          ; b13f: a9 ff       ..       ; A=&FF: initial column counter
    sta fs_spool_handle                                               ; b141: 85 ba       ..       ; Store column counter
    lda #1                                                            ; b143: a9 01       ..       ; One entry per line (Ex format)
    sta fs_work_7                                                     ; b145: 85 b7       ..       ; Store entries per page
    lda #3                                                            ; b147: a9 03       ..       ; FS command code 3: Examine
    sta fs_work_5                                                     ; b149: 85 b5       ..       ; Store command code
    bne setup_ex_request                                              ; b14b: d0 16       ..       ; Branch to set up the *EX request
; ***************************************************************************************
; FSCV reason 5: catalogue (*CAT)
;
; Sets up transfer parameters via set_xfer_params, clears the library bit in
; hazel_fs_lib_flags via the ROR/CLC/ROL idiom that uses carry to preserve other flags,
; and falls through to cat_set_lib_flag to issue the FS examine request. Reached via the
; FSCV vector with reason code 5.
.fscv_5_cat
    jsr set_xfer_params                                               ; b14d: 20 de 93     ..      ; Set transfer parameters
    ldy #0                                                            ; b150: a0 00       ..       ; Y=0: start from entry 0
    ror hazel_fs_lib_flags                                            ; b152: 6e 71 c2    nq.      ; Rotate carry into lib flag
    clc                                                               ; b155: 18          .        ; Clear carry (= current directory)
; &b156 referenced 1 time by &b12b
.cat_set_lib_flag
    rol hazel_fs_lib_flags                                            ; b156: 2e 71 c2    .q.      ; Rotate carry back, clearing bit 7
    lda #3                                                            ; b159: a9 03       ..       ; Three entries per column (Cat)
    sta fs_spool_handle                                               ; b15b: 85 ba       ..       ; Store column counter
    sta fs_work_7                                                     ; b15d: 85 b7       ..       ; Store entries per page
    lda #&0b                                                          ; b15f: a9 0b       ..       ; FS command code &0B: Catalogue
    sta fs_work_5                                                     ; b161: 85 b5       ..       ; Store command code
; &b163 referenced 1 time by &b14b
.setup_ex_request
    jsr save_ptr_to_os_text                                           ; b163: 20 a8 b3     ..      ; Save text pointer
    lda #&ff                                                          ; b166: a9 ff       ..       ; A=&FF: enable escape checking
    sta need_release_tube                                             ; b168: 85 98       ..       ; Set escapable flag
    lda #6                                                            ; b16a: a9 06       ..       ; Command code 6
    sta hazel_txcb_data                                               ; b16c: 8d 05 c1    ...      ; Store in TX buffer
    jsr parse_filename_arg                                            ; b16f: 20 61 b2     a.      ; Parse directory argument
    ldx #1                                                            ; b172: a2 01       ..       ; X=1: offset in buffer
    jsr copy_arg_to_buf                                               ; b174: 20 d6 b2     ..      ; Copy argument to TX buffer
    lda hazel_fs_lib_flags                                            ; b177: ad 71 c2    .q.      ; Get library/FS flags
    lsr a                                                             ; b17a: 4a          J        ; Shift bit 0 to carry
    bcc store_owner_flags                                             ; b17b: 90 02       ..       ; Bit 0 clear: skip
    ora #&40                                                          ; b17d: 09 40       .@       ; Set bit 6 (owner access flag)
; &b17f referenced 1 time by &b17b
.store_owner_flags
    rol a                                                             ; b17f: 2a          *        ; Rotate back
    sta hazel_fs_lib_flags                                            ; b180: 8d 71 c2    .q.      ; Store modified flags
    ldy #&12                                                          ; b183: a0 12       ..       ; Y=&12: FS command for examine
    jsr save_net_tx_cb                                                ; b185: 20 8a 97     ..      ; Send request to file server
    ldx #3                                                            ; b188: a2 03       ..       ; X=3: offset to directory title
    jsr print_10_chars                                                ; b18a: 20 4f b2     O.      ; Print directory title (10 chars)
    jsr print_inline_no_spool                                         ; b18d: 20 95 92     ..      ; Print '('
    equs "("                                                          ; b190: 28          (     
    lda hazel_txcb_objtype                                            ; b191: ad 13 c1    ...      ; Load FS object-type code from hazel_txcb_objtype (file/dir/etc)
    jsr print_dec_3dig_no_spool                                       ; b194: 20 38 b3     8.      ; Print a 3-digit decimal (no spool)
    jsr print_inline_no_spool                                         ; b197: 20 95 92     ..      ; Print ') ' to close the type-code field
    equs ")     "                                                     ; b19a: 29 20 20... )  ...
    ldy hazel_txcb_type                                               ; b1a0: ac 12 c1    ...      ; Read hazel_txcb_type (FS reply opcode)
    bne print_public_label                                            ; b1a3: d0 0b       ..       ; Non-zero (private library): take the public-label branch
    jsr print_inline_no_spool                                         ; b1a5: 20 95 92     ..      ; Print 'Owner' + CR
    equs "Owner", &0d                                                 ; b1a8: 4f 77 6e... Own...
    bne cat_after_label_print                                         ; b1ae: d0 0a       ..       ; Non-zero: branch to cat_after_label_print
; &b1b0 referenced 1 time by &b1a3
